:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --correct: #38b764;
  --wrong: #b13e53;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  font-size: 18px;
  line-height: 1.5;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 2rem 1.5rem;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.8rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  color: var(--accent);
}

#question {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  min-height: 2.5rem;
}

.answers {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 1.5rem;
}

button {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 0.75rem 1.5rem;
  border: 3px solid var(--accent);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, color 0.1s, transform 0.1s;
  min-width: 80px;
}

button:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.answer.correct {
  background: var(--correct);
  border-color: var(--correct);
  color: #fff;
}

.answer.wrong {
  background: var(--wrong);
  border-color: var(--wrong);
  color: #fff;
}

.score-line {
  font-size: 1.2rem;
  margin-bottom: 1.5rem;
}

#score {
  font-weight: 700;
  color: var(--accent);
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  h1 {
    font-size: 1.4rem;
  }
  #question {
    font-size: 1.3rem;
  }
  button {
    font-size: 1rem;
    padding: 0.6rem 1rem;
  }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;
let finished = false;

function render() {
  if (finished) {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
    return;
  }
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  nextBtn.disabled = true;
  answered = false;
}

function handleAnswer(choice) {
  if (answered || finished) return;
  answered = true;
  const q = questions[current];
  const correctBtn = q.correct === 'a' ? answerA : answerB;
  const wrongBtn = q.correct === 'a' ? answerB : answerA;
  if (choice === q.correct) {
    score++;
    scoreEl.textContent = score;
    correctBtn.classList.add('correct');
  } else {
    wrongBtn.classList.add('wrong');
    correctBtn.classList.add('correct');
  }
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!answered) return;
  if (current === 0) {
    current = 1;
    render();
  } else {
    finished = true;
    render();
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  answered = false;
  finished = false;
  scoreEl.textContent = '0';
  render();
});

render();
